function validate([root, val, depth]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  // Rebuild the levels from the level-order list: each node owns the next two slots.
  const levels = [1];
  let slot = 1;
  for (let q = 0; q < levels.length && slot < root.length; q++) {
    for (let side = 0; side < 2 && slot < root.length; side++, slot++) {
      if (root[slot] !== null) levels.push(levels[q] + 1);
    }
  }
  if (slot < root.length) return 'Some values have no parent in the level-order list.';
  if (levels.length > 10000) return 'The tree has at most 10^4 nodes.';
  if (root.some(v => v !== null && (!Number.isInteger(v) || v < -100 || v > 100))) return 'Node values are integers from -100 to 100.';
  if (!Number.isInteger(val) || val < -100000 || val > 100000) return 'val is an integer from -10^5 to 10^5.';
  const height = Math.max(...levels);
  if (!Number.isInteger(depth) || depth < 1 || depth > height + 1) return `depth must be between 1 and ${height + 1} (one more than the tree's level count).`;
  return null;
}

