function addOneRow(root, val, depth) {
  // Level by level: walk down depth - 2 levels with a queue, then rewire every node found there.
  const head = new TreeNode(0, root, null);
  let level = [head];
  for (let d = 1; d < depth; d++) {
    const next = [];
    for (const node of level) {
      if (node.left) next.push(node.left);
      if (node !== head && node.right) next.push(node.right);
    }
    level = next;
  }
  for (const node of level) {
    if (node === head) {
      head.left = new TreeNode(val, head.left, null);
      continue;
    }
    node.left = new TreeNode(val, node.left, null);
    node.right = new TreeNode(val, null, node.right);
  }
  return head.left;
}

