function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 850 + pick(140) : 1 + pick(9);
  // shape 0 attaches anywhere, 1 grows deep from the newest nodes, 2 fills level by level.
  const shape = pick(3);
  const span = size === 'large' ? 100 : rand() < 0.5 ? 3 : 100;
  const value = () => pick(2 * span + 1) - span;
  const nodes = [{ val: value(), left: null, right: null, level: 1 }];
  const open = [nodes[0]];
  while (nodes.length < n) {
    const index = shape === 1 ? Math.max(0, open.length - 1 - pick(2)) : shape === 2 ? 0 : pick(open.length);
    const parent = open[index];
    const side = parent.left === null && (parent.right !== null || shape === 2 || rand() < 0.5) ? 'left' : 'right';
    const child = { val: value(), left: null, right: null, level: parent.level + 1 };
    parent[side] = child;
    if (parent.left !== null && parent.right !== null) open.splice(index, 1);
    nodes.push(child);
    open.push(child);
  }
  const out = [];
  const queue = [nodes[0]];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    if (node === null) { out.push(null); continue; }
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  const height = Math.max(...nodes.map(node => node.level));
  const roll = rand();
  const depth = roll < 0.15 ? 1 : roll < 0.3 ? height + 1 : 1 + pick(height + 1);
  const valSpan = rand() < 0.5 ? 5 : 100000;
  return [out, pick(2 * valSpan + 1) - valSpan, depth];
}
